  "name": "secure_avatar_upserts",
  "query": "insert into storage.buckets (id, name, public)
values ('avatars', 'avatars', true)
on conflict (id) do update set public = excluded.public;

create policy "Users can insert their own avatar"
on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'avatars'
  and name = ((select auth.uid())::text || '/avatar.png')
);

create policy "Users can select their own avatar for upsert"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'avatars'
  and name = ((select auth.uid())::text || '/avatar.png')
);

create policy "Users can update their own avatar"
on storage.objects
for update
to authenticated
using (
  bucket_id = 'avatars'
  and name = ((select auth.uid())::text || '/avatar.png')
)
with check (
  bucket_id = 'avatars'
  and name = ((select auth.uid())::text || '/avatar.png')
);"
}

